<script setup lang="ts">
import { ChevronLeft, ChevronRight, Eye, FilePlus2, Search } from '@lucide/vue'
definePageMeta({ middleware: 'auth', ssr: false })
interface ReceiptRow { id: string; amount: string | null; concepts: string | null; otherConcept: string | null; paymentMethod: string | null; transactionDate: string | null; registeredAt: string; contract: { id: string; contractNumber: string; holderName: string; holderDni: string } }
interface ResponseData { data: ReceiptRow[]; pagination: { page: number; limit: number; total: number; totalPages: number } }
const search = ref(''); const page = ref(1); const loading = ref(true); const error = ref(''); const receipts = ref<ReceiptRow[]>([]); const pagination = ref<ResponseData['pagination']>({ page: 1, limit: 15, total: 0, totalPages: 0 })
const loadReceipts = async () => { loading.value = true; error.value = ''; try { const response = await $fetch<ResponseData>('/api/receipts', { query: { page: page.value, search: search.value || undefined }, credentials: 'include' }); receipts.value = response.data; pagination.value = response.pagination } catch (err: any) { error.value = err?.data?.statusMessage || 'No pudimos cargar los recibos.' } finally { loading.value = false } }
const submitSearch = async () => { page.value = 1; await loadReceipts() }; const goToPage = async (nextPage: number) => { if (nextPage < 1 || nextPage > pagination.value.totalPages || nextPage === page.value) return; page.value = nextPage; await loadReceipts() }
const formatDate = (value: string | null) => value ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'short' }).format(new Date(value)) : '—'; const formatCurrency = (value: string | null) => value ? new Intl.NumberFormat('es-PE', { style: 'currency', currency: 'PEN' }).format(Number(value)) : '—'; const concept = (row: ReceiptRow) => row.concepts || (row.otherConcept ? `OTROS: ${row.otherConcept}` : '—')
onMounted(loadReceipts)
</script>
<template><div class="min-h-[100dvh] bg-muted/20"><AppHeader title="Recibos" subtitle="Consulta de todos los pagos registrados" /><main class="mx-auto max-w-[1500px] space-y-6 px-4 py-8 sm:px-6 lg:px-8"><section class="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h1 class="text-3xl font-semibold tracking-tight">Recibos</h1><p class="mt-1 text-muted-foreground">{{ pagination.total }} recibos registrados.</p></div><form class="flex w-full gap-2 sm:w-auto" @submit.prevent="submitSearch"><div class="relative w-full sm:w-80"><Search class="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><UiInput v-model="search" class="pl-9" placeholder="Buscar contrato, titular o DNI" /></div><UiButton type="submit" variant="outline" size="icon" aria-label="Buscar"><Search class="size-4" /></UiButton></form></section><UiCard><UiCardContent class="p-0"><div v-if="loading" class="space-y-3 p-6"><UiSkeleton v-for="row in 6" :key="row" class="h-12 w-full" /></div><UiAlert v-else-if="error" variant="destructive" class="m-6"><UiAlertDescription>{{ error }}</UiAlertDescription></UiAlert><div v-else-if="!receipts.length" class="flex min-h-64 flex-col items-center justify-center px-6 text-center"><FilePlus2 class="mb-3 size-8 text-muted-foreground" /><p class="font-medium">No hay recibos registrados</p></div><UiTable v-else><UiTableHeader><UiTableRow><UiTableHead>Contrato</UiTableHead><UiTableHead>Titular</UiTableHead><UiTableHead>Concepto</UiTableHead><UiTableHead>Importe</UiTableHead><UiTableHead>Forma de pago</UiTableHead><UiTableHead>Fecha</UiTableHead><UiTableHead class="text-right">Acciones</UiTableHead></UiTableRow></UiTableHeader><UiTableBody><UiTableRow v-for="receipt in receipts" :key="receipt.id"><UiTableCell class="font-semibold text-primary">{{ receipt.contract.contractNumber }}</UiTableCell><UiTableCell><div class="max-w-56 truncate font-medium uppercase">{{ receipt.contract.holderName }}</div><div class="text-xs text-muted-foreground">{{ receipt.contract.holderDni }}</div></UiTableCell><UiTableCell>{{ concept(receipt) }}</UiTableCell><UiTableCell class="whitespace-nowrap font-semibold">{{ formatCurrency(receipt.amount) }}</UiTableCell><UiTableCell>{{ receipt.paymentMethod || '—' }}</UiTableCell><UiTableCell class="whitespace-nowrap">{{ formatDate(receipt.transactionDate || receipt.registeredAt) }}</UiTableCell><UiTableCell><div class="flex justify-end"><UiButton variant="ghost" size="icon" title="Ver recibo" aria-label="Ver recibo" as-child><NuxtLink :to="`/recibo/${receipt.id}`"><Eye class="size-4" /></NuxtLink></UiButton></div></UiTableCell></UiTableRow></UiTableBody></UiTable></UiCardContent><UiCardFooter v-if="!loading && pagination.totalPages > 1" class="flex-col gap-4 border-t sm:flex-row sm:justify-between"><p class="text-sm text-muted-foreground">Página <span class="font-semibold text-foreground">{{ pagination.page }}</span> de {{ pagination.totalPages }}</p><nav aria-label="Paginación de recibos" class="flex items-center gap-1"><UiButton variant="outline" size="icon" class="size-8" :disabled="page <= 1" @click="goToPage(page - 1)"><ChevronLeft class="size-4" /></UiButton><UiButton variant="outline" size="icon" class="size-8" :disabled="page >= pagination.totalPages" @click="goToPage(page + 1)"><ChevronRight class="size-4" /></UiButton></nav></UiCardFooter></UiCard></main></div></template>
